from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def p(status="captured", amt="100.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# rounding
x=p(); process_refund_request(x,"49.999","u",T0); print("round", x.refunded_amount)
# full refund
x=p(); process_refund_request(x,"100.00","u",T0); print("full", x.refunded_amount, x.status)
# zero/negative
for a in ["0","-1"]:
    try: process_refund_request(p(),a,"u",T0)
    except BillingError as e: print("err",a,e.code)
# wrong state
try: process_refund_request(p("authorized"),"1","u",T0)
except BillingError as e: print("state",e.code)
# over refund
x=p(); process_refund_request(x,"60","u",T0)
try: process_refund_request(x,"50","u",T0)
except BillingError as e: print("over",e.code)
# approval
try: process_refund_request(p("captured","1000.00"),"600","u",T0)
except BillingError as e: print("approval",e.code)
x=p("captured","1000.00"); process_refund_request(x,"600","u",T0,approved_by="boss"); print("approved",x.refunded_amount)
# idempotency: retry after full refund returns unchanged
x=p(); process_refund_request(x,"100","u",T0,idempotency_key="k1")
r=process_refund_request(x,"100","u",T0,idempotency_key="k1"); print("idem",r.refunded_amount,r.status)
# naive datetime
try: process_refund_request(p(),"1","u",datetime(2026,1,1))
except BillingError as e: print("naive",e.code)
EOF"}

